raw_chrome.base_css:
:root{color-scheme: dark; --bg: oklch(12% 0.05 30); --bg2: oklch(15% 0.04 30); --charcoal: oklch(18% 0.03 30); --ochre: oklch(76% 0.14 68); --cheddar: oklch(72% 0.17 54); --jalapeno: oklch(67% 0.14 145); --ink: oklch(97% 0.01 30); --muted: rgba(255, 255, 255, .66);}
*{box-sizing: border-box;}
html{scroll-behavior: smooth;}
body{margin: 0px; overflow-x: hidden; font-family: "Inter Tight", sans-serif; background: radial-gradient(circle at 18% 10%, rgba(222, 141, 57, 0.13), transparent 16%), radial-gradient(circle at 82% 14%, rgba(90, 176, 84, 0.08), transparent 14%), linear-gradient(oklch(0.12 0.05 30) 0%, oklch(0.1 0.045 30) 48%, oklch(0.08 0.04 30) 100%); color: white;}
body::before{content: ""; position: fixed; inset: 0px; pointer-events: none; background-image: linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px), linear-gradient(135deg, transparent 0px, transparent 48%, rgba(255, 255, 255, 0.024) 48%, rgba(255, 255, 255, 0.024) 52%, transparent 52%); background-size: 120px 120px, 120px 120px, 280px 280px; opacity: 0.22; z-index: -2;}
::view-transition-old(root), ::view-transition-new(root){animation-duration: 0.72s; animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);}
*, ::before, ::after{--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ;}
::backdrop{--tw-border-spacing-x: 0; --tw-border-spacing-y: 0; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-gradient-from-position: ; --tw-gradient-via-position: ; --tw-gradient-to-position: ; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; --tw-contain-size: ; --tw-contain-layout: ; --tw-contain-paint: ; --tw-contain-style: ;}
*, ::after, ::before{box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235);}
::after, ::before{--tw-content: '';}
html{line-height: 1.5; text-size-adjust: 100%; tab-size: 4; font-family: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-feature-settings: normal; font-variation-settings: normal; -webkit-tap-highlight-color: transparent;}
body{margin: 0px; line-height: inherit;}
a{color: inherit; text-decoration: inherit;}
button{font-family: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: 100%; font-weight: inherit; line-height: inherit; letter-spacing: inherit; color: inherit; margin: 0px; padding: 0px;}
button{text-transform: none;}
button{appearance: button; background-color: transparent; background-image: none;}
::-webkit-inner-spin-button, ::-webkit-outer-spin-button{height: auto;}
::-webkit-search-decoration{appearance: none;}
::-webkit-file-upload-button{appearance: button; font: inherit;}
button{cursor: pointer;}
:disabled{cursor: default;}

raw_chrome.util_css:
.display{font-family: Fraunces, serif; letter-spacing: -0.06em;}
.smoked{background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.09); backdrop-filter: blur(20px) contrast(0.95); box-shadow: rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(0, 0, 0, 0.35) 0px 18px 60px;}
.textured-touch{position: relative; overflow: hidden; border-radius: 1rem; background: linear-gradient(rgba(227, 178, 104, 0.88), rgba(183, 122, 59, 0.82)), linear-gradient(135deg, rgba(255, 255, 255, 0.08), transparent 45%); border: 1px solid rgba(255, 255, 255, 0.12); color: rgb(28, 20, 13); box-shadow: rgba(255, 255, 255, 0.4) 0px 1px 0px inset, rgba(0, 0, 0, 0.08) 0px -12px 18px inset, rgba(0, 0, 0, 0.3) 0px 20px 48px; transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.45s;}
.textured-touch::before{content: ""; position: absolute; inset: 0px; background-image: linear-gradient(135deg, rgba(0, 0, 0, 0.12) 0px, rgba(0, 0, 0, 0.12) 1px, transparent 1px, transparent 100%), linear-gradient(45deg, rgba(0, 0, 0, 0.06) 0px, rgba(0, 0, 0, 0.06) 1px, transparent 1px, transparent 100%); opacity: 0.28; pointer-events: none; mix-blend-mode: multiply;}
.textured-touch::after{content: ""; position: absolute; inset: -110%; background: radial-gradient(circle at 30% 40%, rgba(255, 255, 255, 0.35), transparent 16%), radial-gradient(circle at 55% 60%, rgba(255, 255, 255, 0.18), transparent 20%), linear-gradient(120deg, transparent 44%, rgba(255, 255, 255, 0.72) 50%, transparent 56%); transform: translateX(-140%) rotate(12deg); animation: 8s ease-in-out 0s infinite normal none running sheen; pointer-events: none; mix-blend-mode: screen; filter: blur(0.2px);}
.textured-touch:hover{transform: translateY(-4px); box-shadow: rgba(255, 255, 255, 0.48) 0px 1px 0px inset, rgba(0, 0, 0, 0.08) 0px -12px 18px inset, rgba(0, 0, 0, 0.36) 0px 28px 56px;}
.textured-touch:active{transform: translateY(1px) scale(0.99);}
.sizzle{position: relative; overflow: hidden; border-radius: 1rem; background: linear-gradient(rgba(235, 170, 84, 0.24), rgba(255, 255, 255, 0.06)); border: 1px solid rgba(235, 170, 84, 0.24); color: white; backdrop-filter: blur(20px) contrast(0.95); box-shadow: rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(0, 0, 0, 0.34) 0px 20px 48px; transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.45s, border-color 0.35s;}
.sizzle::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at 20% 30%, rgba(255, 255, 255, 0.18), transparent 12%), radial-gradient(circle at 70% 68%, rgba(255, 255, 255, 0.12), transparent 10%), radial-gradient(circle at 55% 45%, rgba(255, 255, 255, 0.14), transparent 10%); opacity: 0; transform: scale(0.9); transition: 0.5s; pointer-events: none;}
.sizzle::after{content: ""; position: absolute; inset: -100%; background: linear-gradient(120deg, transparent 46%, rgba(255, 255, 255, 0.58) 50%, transparent 54%); transform: translateX(-130%) rotate(10deg); animation: 9s ease-in-out 0s infinite normal none running sheen; pointer-events: none; mix-blend-mode: screen;}
.sizzle:hover{transform: translateY(-4px); border-color: rgba(235, 170, 84, 0.4); box-shadow: rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(0, 0, 0, 0.42) 0px 26px 60px, rgba(235, 170, 84, 0.12) 0px 0px 0px 1px;}
.sizzle:hover::before{opacity: 1; transform: scale(1.2);}
.hero{position: relative; min-height: 100svh; background: var(--bg); overflow: hidden;}
.hero-grid{position: relative; z-index: 4; width: min(1600px, 100% - 32px); margin: 0px auto; min-height: 100svh; display: grid; grid-template-columns: 0.4fr 0.6fr; gap: 0px; padding-top: 110px;}
.hero-copy{position: relative; z-index: 30; display: flex; align-items: center; justify-content: center; padding: 56px 22px 56px 0px;}
.hero-copy-inner{width: 100%; max-width: 560px; padding: 28px 28px 32px; background: rgba(14, 14, 14, 0.44); border: 1px solid rgba(255, 255, 255, 0.08); backdrop-filter: blur(20px) contrast(0.95); box-shadow: rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(0, 0, 0, 0.38) 0px 24px 60px;}
.hero-kicker{display: inline-flex; align-items: center; gap: 10px; padding: 10px 14px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; color: rgba(255, 255, 255, 0.7);}
.hero-kicker span{width: 8px; height: 8px; background: var(--ochre); display: inline-block;}
.hero-title{margin-top: 22px; font-size: clamp(4.2rem, 10vw, 8.6rem); line-height: 0.82; letter-spacing: -0.08em; color: white; text-shadow: rgba(0, 0, 0, 0.22) 0px 8px 20px, rgba(235, 170, 84, 0.06) 0px 0px 20px;}
.heat-wave{display: inline-block; animation: 6.5s ease-in-out 0s infinite normal none running heatWave; transform-origin: left center;}
.hero-text{margin-top: 20px; color: rgba(255, 255, 255, 0.82); font-family: "PP Neue Montreal", "Inter Tight", sans-serif; line-height: 1.95; font-size: 16px;}
.specs{margin-top: 22px; display: flex; flex-wrap: wrap; gap: 10px;}
.specs span{padding: 10px 12px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); text-transform: uppercase; letter-spacing: 0.2em; font-size: 10px; color: rgba(255, 255, 255, 0.72);}
.hero-cta{display: flex; gap: 12px; flex-wrap: wrap; margin-top: 26px;}
.hero-cta button{height: 54px; padding: 0px 20px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; cursor: pointer; font-size: 10px; letter-spacing: 0.28em; text-transform: uppercase;}
.hero-visual{position: relative; min-height: 100svh; overflow: hidden; z-index: 10;}
.splash-shell{position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 120%; height: 110%; display: flex; align-items: center; justify-content: center;}
.splash-shell video{width: 100%; height: 100%; object-fit: contain; object-position: center center;}
.sauce-glow{position: absolute; inset: 0px; background: radial-gradient(circle at 18% 26%, rgba(0, 0, 0, 0.28), transparent 18%), radial-gradient(circle at 52% 24%, rgba(255, 228, 195, 0.12), transparent 16%), radial-gradient(circle at 70% 62%, rgba(110, 208, 76, 0.16), transparent 16%), linear-gradient(rgba(0, 37, 32, 0.08), rgba(0, 0, 0, 0.4)); pointer-events: none;}
.ingredient-field{position: absolute; inset: 0px; z-index: 22; pointer-events: none; overflow: hidden;}
.seed, .drip{position: absolute; background: rgba(255, 242, 216, 0.9); transform-origin: center center; filter: drop-shadow(rgba(255, 193, 85, 0.12) 0px 0px 8px); animation: 10s linear 0s infinite normal none running flight;}
.seed{width: 10px; height: 4px; border-radius: 2px;}
.drip{width: 18px; height: 6px; border-radius: 2px; background: rgba(255, 126, 40, 0.9);}
.heat-scrim{position: absolute; left: 0px; top: 0px; bottom: 0px; width: 42%; z-index: 28; background: linear-gradient(90deg, rgba(12, 12, 12, 0.64), rgba(12, 12, 12, 0.32) 55%, transparent 100%); pointer-events: none;}
.section{padding: 120px 0px;}
.shell{width: min(1600px, 100% - 32px); margin: 0px auto;}
.ledger{position: relative; padding: 32px 0px 8px;}
.ledger::before{content: ""; position: absolute; left: 0px; right: 0px; top: 0px; height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 153, 60, 0.35), rgba(118, 204, 86, 0.24), transparent);}
.ledger-head{display: flex; justify-content: space-between; gap: 24px; align-items: flex-end; margin-bottom: 26px;}
.ledger-head h2{font-size: clamp(2.8rem, 5.7vw, 6rem); line-height: 0.88; letter-spacing: -0.07em; color: white;}
.ledger-head p{max-width: 420px; line-height: 1.95; color: rgba(255, 255, 255, 0.66);}
.assemble{opacity: 0; transform: translateY(30px); animation-duration: 0.9s; animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1); animation-delay: 0s; animation-iteration-count: 1; animation-direction: normal; animation-fill-mode: forwards; animation-play-state: running; animation-name: assembleIn; animation-timeline: view(); animation-range: entry 12% cover 32%;}
.strip{display: grid; grid-template-columns: 0.9fr 1.1fr 0.4fr; gap: 18px; align-items: end; padding: 22px 0px; border-top: 1px solid rgba(255, 255, 255, 0.09); border-bottom: 1px solid rgba(255, 255, 255, 0.05); position: relative; overflow: hidden;}
.strip::before{content: ""; position: absolute; inset: 0px; background: linear-gradient(90deg, rgba(255, 153, 60, 0.08), transparent 35%, rgba(118, 204, 86, 0.06) 75%, transparent 100%); opacity: 0.55; pointer-events: none;}
.strip:nth-child(2){margin-left: 6%; width: 88%;}
.strip:nth-child(3){margin-left: 11%; width: 82%;}
.strip:nth-child(4){margin-left: 4%; width: 92%;}
.strip .label{text-transform: uppercase; letter-spacing: 0.3em; font-size: 10px; color: rgba(255, 255, 255, 0.55);}
.strip h3{margin-top: 12px; font-size: clamp(1.8rem, 3.2vw, 3.4rem); line-height: 0.94; letter-spacing: -0.05em; color: white;}
.strip p{margin-top: 16px; max-width: 48ch; line-height: 1.9; color: rgba(255, 255, 255, 0.68);}
.strip .metric{justify-self: end; font-size: clamp(3rem, 6vw, 5.4rem); line-height: 1; letter-spacing: -0.08em; color: rgba(255, 255, 255, 0.14);}
.text-stack{padding: 120px 0px; background: radial-gradient(circle at 18% 18%, rgba(255, 153, 60, 0.09), transparent 18%), radial-gradient(circle at 84% 28%, rgba(118, 204, 86, 0.08), transparent 16%), linear-gradient(rgba(17, 17, 17, 0.55), rgba(8, 8, 8, 0.92));}
.text-stack-shell{width: min(1600px, 100% - 32px); margin: 0px auto; display: grid; grid-template-columns: 1.05fr 0.95fr; gap: 24px; align-items: start;}
.recipe-wall{padding: 48px; background: linear-gradient(rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.024)), linear-gradient(135deg, rgba(255, 255, 255, 0.035), transparent 42%); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.34) 0px 24px 80px;}
.recipe-wall h2{font-size: clamp(3rem, 6vw, 6rem); line-height: 0.88; letter-spacing: -0.07em; color: white;}
.recipe-wall p{margin-top: 18px; max-width: 680px; line-height: 2; color: rgba(255, 255, 255, 0.68); font-family: "PP Neue Montreal", "Inter Tight", sans-serif; font-size: 16px;}
.layer-rail{position: relative; display: flex; flex-direction: column; gap: 16px; padding-top: 14px;}
.layer{min-height: 128px; padding: 20px 22px; display: flex; flex-direction: column; justify-content: space-between; background: linear-gradient(rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03)), linear-gradient(135deg, rgba(255, 255, 255, 0.05), transparent 65%); border: 1px solid rgba(255, 255, 255, 0.07); box-shadow: rgba(0, 0, 0, 0.24) 0px 18px 44px; transform: translateX(0px); transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.45s; opacity: 0;}
.layer:nth-child(2){margin-left: 6%;}
.layer:nth-child(3){margin-left: 12%;}
.layer:nth-child(4){margin-left: 4%;}
.layer.in{opacity: 1;}
.layer .top{display: flex; justify-content: space-between; gap: 18px; align-items: flex-start;}
.layer .tag{text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; color: rgba(255, 255, 255, 0.55);}
.layer .name{font-size: clamp(1.5rem, 2.8vw, 2.7rem); line-height: 0.95; letter-spacing: -0.05em; color: white;}
.layer .bar{height: 8px; background: rgba(255, 255, 255, 0.08); overflow: hidden; margin-top: 12px;}
.layer .bar span{display: block; height: 100%; width: var(--w, 70%); background: linear-gradient(90deg, rgba(255, 153, 60, 0.75), rgba(118, 204, 86, 0.75));}
.counter{margin-top: 20px; display: flex; gap: 12px; flex-wrap: wrap;}
.counter span{padding: 10px 12px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); text-transform: uppercase; letter-spacing: 0.2em; font-size: 10px; color: rgba(255, 255, 255, 0.7);}
.finish{padding: 120px 0px 110px;}
.finish-shell{width: min(1600px, 100% - 32px); margin: 0px auto; display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 24px; align-items: stretch;}
.menu-board{padding: 56px; background: linear-gradient(rgba(255, 255, 255, 0.067), rgba(255, 255, 255, 0.02)), linear-gradient(135deg, rgba(235, 170, 84, 0.08), transparent 35%, rgba(118, 204, 86, 0.06) 75%); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.34) 0px 22px 70px;}
.menu-board h2{font-size: clamp(3rem, 6vw, 6rem); line-height: 0.88; letter-spacing: -0.07em; color: white;}
.menu-board p{margin-top: 18px; max-width: 740px; color: rgba(255, 255, 255, 0.68); line-height: 2; font-family: "PP Neue Montreal", "Inter Tight", sans-serif;}
.board-actions{display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px;}
.info-stack{display: flex; flex-direction: column; gap: 16px;}
.info{min-height: 160px; padding: 24px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.24) 0px 18px 44px;}
.info .label{text-transform: uppercase; letter-spacing: 0.28em; font-size: 10px; color: rgba(255, 255, 255, 0.52);}
.info .value{margin-top: 16px; font-size: clamp(2.4rem, 4vw, 4.2rem); line-height: 0.92; letter-spacing: -0.06em; color: white;}
.footer-line{margin-top: 28px; height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.22), transparent);}
.foot{padding: 0px 0px 84px;}
.foot-shell{width: min(1600px, 100% - 32px); margin: 0px auto; padding: 28px 32px 34px; background: rgba(255, 255, 255, 0.035); border: 1px solid rgba(255, 255, 255, 0.08); box-shadow: rgba(0, 0, 0, 0.22) 0px 22px 70px;}
.foot-grid{display: flex; justify-content: space-between; gap: 24px; align-items: flex-end; flex-wrap: wrap;}
.foot-grid .left{max-width: 760px;}
.foot-grid h3{font-size: clamp(2.2rem, 4vw, 4.6rem); line-height: 0.92; letter-spacing: -0.06em; color: white;}
.foot-grid p{margin-top: 16px; color: rgba(255, 255, 255, 0.68); line-height: 1.95;}
.tags{display: flex; flex-wrap: wrap; gap: 12px; justify-content: flex-end;}
.tags span{padding: 10px 12px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.08); text-transform: uppercase; letter-spacing: 0.2em; font-size: 10px; color: rgba(255, 255, 255, 0.72);}
.reveal{opacity: 0; transform: translateY(28px); transition: opacity 0.8s, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);}
.reveal.in{opacity: 1; transform: translateY(0px);}
@keyframes assembleIn { 
  100% { opacity: 1; transform: translateY(0px); }
}
@keyframes heatWave { 
  0%, 100% { transform: translateX(0px) skewX(0deg); }
  25% { transform: translateX(1px) skewX(-1deg); }
  50% { transform: translateX(-1px) skewX(1deg); }
  75% { transform: translateX(0.5px) skewX(-0.6deg); }
}
@keyframes sheen { 
  100% { transform: translateX(240%) rotate(12deg); }
}
@keyframes flight { 
  0% { transform: translate3d(var(--x0), var(--y0), 0) rotate(var(--r0)); opacity: 0; }
  10% { opacity: 1; }
  100% { transform: translate3d(var(--x1), var(--y1), 0) rotate(var(--r1)); opacity: 0; }
}
@media (max-width: 1180px){.hero-grid{grid-template-columns: 1fr; padding-top: 96px;}}
@media (max-width: 1180px){.hero-copy{justify-content: flex-start; padding: 36px 0px 18px;}}
@media (max-width: 1180px){.hero-visual{min-height: 70vh;}}
@media (max-width: 1180px){.hero-visual{order: -1;}}
@media (max-width: 1180px){.heat-scrim{width: 55%;}}
@media (max-width: 1180px){.text-stack-shell, .finish-shell{grid-template-columns: 1fr;}}
@media (max-width: 1180px){.strip{grid-template-columns: 1fr auto;}}
@media (max-width: 1180px){.strip .metric{grid-column: 2; align-self: end;}}
@media (max-width: 1180px){.foot-grid{align-items: flex-start;}}
@media (max-width: 760px){.hero-grid, .shell, .text-stack-shell, .finish-shell, .foot-shell{width: min(100% - 20px, 1600px);}}
@media (max-width: 760px){.hero-copy-inner, .recipe-wall, .menu-board{padding: 24px;}}
@media (max-width: 760px){.hero-title{font-size: clamp(3.2rem, 16vw, 6rem);}}
@media (max-width: 760px){.ledger-head{flex-direction: column; align-items: flex-start;}}
@media (max-width: 760px){.strip{grid-template-columns: 1fr;}}
@media (max-width: 760px){.strip .metric{justify-self: start;}}
