raw_chrome.header_css:
.copy{font-family: "Inter Tight", sans-serif;}
.slat-bar{position: fixed; top: 0px; left: 0px; right: 0px; z-index: 80; background: rgba(10, 10, 10, 0.74); border-bottom: 1px solid rgba(255, 255, 255, 0.08); backdrop-filter: blur(14px) contrast(0.96);}
.slat-inner{width: min(1600px, 100% - 32px); margin: 0px auto; display: grid; grid-template-columns: 1.1fr 1.1fr 0.8fr; gap: 18px; align-items: stretch; padding: 16px 0px;}
.slat-brand, .slat-nav, .slat-action{min-height: 58px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.04); display: flex; align-items: center; padding: 0px 18px;}
.slat-brand{justify-content: flex-start; gap: 14px;}
.brand-mark{width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: rgba(255, 255, 255, 0.08); border: 1px solid rgba(255, 255, 255, 0.08);}
.slat-nav{justify-content: center; gap: 18px; text-transform: uppercase; letter-spacing: 0.26em; font-size: 10px; color: rgba(255, 255, 255, 0.62); overflow-x: auto; scrollbar-width: none;}
.slat-nav::-webkit-scrollbar{display: none;}
.slat-nav a{color: inherit; text-decoration: none; white-space: nowrap; transition: 0.25s;}
.slat-nav a:hover{color: rgb(242, 185, 101);}
.slat-action{justify-content: flex-end; gap: 12px;}
.mini-meter{width: 100%; max-width: 220px; height: 8px; background: rgba(255, 255, 255, 0.08); overflow: hidden;}
.mini-meter span{display: block; width: 72%; height: 100%; background: linear-gradient(90deg, rgba(237, 176, 84, 0.86), rgba(255, 232, 181, 0.95));}
@media (max-width: 1180px){.slat-inner{grid-template-columns: 1fr auto;}}
@media (max-width: 1180px){.slat-nav{display: none;}}
@media (max-width: 760px){.slat-inner{width: min(100% - 20px, 1600px);}}
